import React from 'react';

function About() {
  return (
    <section id="about" className="about">
      <div className="container">
        <h2>About Us</h2>
        <p>At the forefront of innovation, we aim to contribute to a <span className="aboutHighlight">Cleaner, Sustainable Future</span> by leveraging cutting-edge Solar Solutions. Our <span className="aboutHighlight">commitment to Excellence and Expertise</span>  empowers individuals and businesses to reduce their carbon footprint while optimizing energy performance.</p>
        <ul>
          <li><h3>Core Purpose:</h3> Making renewable energy accessible at reasonable costs.</li>
          <li><h3>Values:</h3> Integrity, Teamwork, Customer Centricity, Innovation.</li>
        </ul>
      </div>
    </section>
  );
}

export default About;

